#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "A/s".parse::<ElectricCurrentGradientUnit>(),
        Ok(ElectricCurrentGradientUnit::AmperePerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "A/s").parse::<ElectricCurrentGradient>(),
        Ok(ElectricCurrentGradient::new(
            2.5,
            ElectricCurrentGradientUnit::AmperePerSecond
        ))
    );
    assert_eq!(
        "mA/s".parse::<ElectricCurrentGradientUnit>(),
        Ok(ElectricCurrentGradientUnit::MilliamperePerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "mA/s").parse::<ElectricCurrentGradient>(),
        Ok(ElectricCurrentGradient::new(
            2.5,
            ElectricCurrentGradientUnit::MilliamperePerSecond
        ))
    );
    assert_eq!(
        "A/min".parse::<ElectricCurrentGradientUnit>(),
        Ok(ElectricCurrentGradientUnit::AmperePerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "A/min").parse::<ElectricCurrentGradient>(),
        Ok(ElectricCurrentGradient::new(
            2.5,
            ElectricCurrentGradientUnit::AmperePerMinute
        ))
    );
    assert_eq!(
        "mA/min".parse::<ElectricCurrentGradientUnit>(),
        Ok(ElectricCurrentGradientUnit::MilliamperePerMinute)
    );
    assert_eq!(
        format!("2.5 {}", "mA/min").parse::<ElectricCurrentGradient>(),
        Ok(ElectricCurrentGradient::new(
            2.5,
            ElectricCurrentGradientUnit::MilliamperePerMinute
        ))
    );
    assert_eq!(
        "A/ms".parse::<ElectricCurrentGradientUnit>(),
        Ok(ElectricCurrentGradientUnit::AmperePerMillisecond)
    );
    assert_eq!(
        format!("2.5 {}", "A/ms").parse::<ElectricCurrentGradient>(),
        Ok(ElectricCurrentGradient::new(
            2.5,
            ElectricCurrentGradientUnit::AmperePerMillisecond
        ))
    );
    assert_eq!(
        "A/μs".parse::<ElectricCurrentGradientUnit>(),
        Ok(ElectricCurrentGradientUnit::AmperePerMicrosecond)
    );
    assert_eq!(
        format!("2.5 {}", "A/μs").parse::<ElectricCurrentGradient>(),
        Ok(ElectricCurrentGradient::new(
            2.5,
            ElectricCurrentGradientUnit::AmperePerMicrosecond
        ))
    );
    assert_eq!(
        "A/ns".parse::<ElectricCurrentGradientUnit>(),
        Ok(ElectricCurrentGradientUnit::AmperePerNanosecond)
    );
    assert_eq!(
        format!("2.5 {}", "A/ns").parse::<ElectricCurrentGradient>(),
        Ok(ElectricCurrentGradient::new(
            2.5,
            ElectricCurrentGradientUnit::AmperePerNanosecond
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<ElectricCurrentGradient>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = ElectricCurrentGradient::from_base(6.0);
    let b = ElectricCurrentGradient::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = ElectricCurrentGradient::<i64>::from_base(7);
    let b = ElectricCurrentGradient::<i64>::from_base(2);
    assert_eq!(a + b, ElectricCurrentGradient::from_base(9));
    assert_eq!(a % b, ElectricCurrentGradient::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<ElectricCurrentGradient<i64>>(),
        ElectricCurrentGradient::from_base(9)
    );
}
